// Normalize text: lowercase, straighten curly apostrophes,
// normalize common punctuation/whitespace.
const raw = String($json.feedback_text || "").trim();

const text = raw
  .toLowerCase()
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/\s+/g, " ")
  .trim();

let category = "Other";

/*
 * CATEGORY
 *
 * Order matters:
 * 1. Very specific operational/data problems first
 * 2. Security/access/integration problems
 * 3. Performance/bugs
 * 4. Feature requests
 * 5. Usability/praise
 */

// Support follow-up / ticket status
if (
  /waiting for (an )?(update|response|reply)|get back to me|follow[- ]?up|update on (our|my) (request|ticket|issue)|request no\.?|ticket (no|#)|status of (my|our) (request|ticket)/.test(text)
) {
  category = "Support Follow-up";

// Data accuracy / incorrect or inconsistent numbers
} else if (
  /incorrect|wrong|inaccurate|doesn't match|does not match|didn't match|did not match|mismatch|discrepanc|numbers (are|were) wrong|headcount .* (wrong|incorrect)|figures .* (wrong|incorrect)|data .* (wrong|incorrect)|missing .* (employees|records)|employees .* missing|record(s)? .* missing|csv export .* missing|export .* missing|data completeness/.test(text)
) {
  category = "Data Accuracy";

// Data synchronization / freshness
} else if (
  /sync|synchroni[sz]|last synced|last sync|data freshness|real[- ]?time|real time|updated in real time|data .* (stale|out of date)|stale data|when .* updated|timestamp .* data/.test(text)
) {
  category = "Data Sync";

// Import / data ingestion
} else if (
  /import|upload|spreadsheet|employee file|file format|rejected rows|rows .* rejected|failed import|import failed|upload failed|couldn't import|could not import|can't import|cannot import|unable to import/.test(text)
) {
  category = "Data Import";

// Access control / permissions / authentication
} else if (
  /role[- ]based|role based|permissions?|permission level|access control|access controls|restricted access|report[- ]level permissions?|who can (view|see|edit)|sensitive .* (data|information)|ss o|sso|single sign[- ]on|identity provider|okta|authentication|invite another admin|admin access/.test(text)
) {
  category = "Access & Security";

// Integrations / API
} else if (
  /integrat(e|ion|ions|ing)|hris|payroll system|slack|microsoft teams|teams notifications?|api\b|internal dashboard|connect .* system|connect .* platform|pull .* data .* (dashboard|system)/.test(text)
) {
  category = "Integration";

// Reporting / exports
} else if (
  /export|download|csv|excel|pdf|report(s)?|scheduled report|schedule .* report|emailed .* report|email .* report|weekly .* report|monthly .* report|custom report|historical reports?|customize reports?/.test(text)
) {
  category = "Reporting & Export";

// Performance
} else if (
  /slow|too slow|lag|laggy|loading|load(ed|s)? (slow|faster)|performance|takes too long|take(s)? forever|time(s|d)? ?out|tim(e|ing) out|30[- ]?60 seconds|two minutes|few seconds|peak hours?|reporting cycle/.test(text)
) {
  category = "Performance";

// Bugs / crashes / failures
} else if (
  /crash|crashes|crashed|broken|bug|fail|failed|failure|doesn't work|does not work|not working|isn't working|is not working|haven't been working|stopped working|can't open|cannot open|unable to save|unable to .* changes|lost changes|page .* crash|filter .* crash|filters? reset|custom field .* disappeared|disappeared from reports?/.test(text)
) {
  category = "Bug";

// Analytics / insights
} else if (
  /actionable insights?|recommendations?|recommended dashboard|suggested next steps?|turnover .* (why|increasing)|why .* turnover|attrition risk|predictive analytics|predictive|contributing factors?|employee engagement|workforce trends?|business performance|workforce planning|headcount planning|hiring needs?/.test(text)
) {
  category = "Analytics & Insights";

// Benchmarking
} else if (
  /benchmark|benchmarking|industry data|industry benchmark|compare .* (companies|company)|similar size|same industry|industry-specific|anonymized industry/.test(text)
) {
  category = "Benchmarking";

// Audit / compliance
} else if (
  /audit logs?|audit trail|who viewed|who edited|who exported|who deleted|viewed .* sensitive|edited .* sensitive|exported .* sensitive|deleted .* sensitive|compliance deadline|compliance alert/.test(text)
) {
  category = "Audit & Compliance";

// Customization / bulk operations
} else if (
  /customiz(e|ation)|customise|custom field|custom fields?|change the date range|comparison period|metrics shown|custom charts?|customize charts?|bulk edit|bulk editing|update .* (50|multiple|many) employees|dark mode|multi[- ]language|multiple languages?|localized reports?/.test(text)
) {
  category = "Customization";

// Pricing
} else if (
  /pricing|price|cost|expensive|justify .* cost|plan .* grow|growing (business|team)|flexible plan|pricing .* (team|business)|team grows/.test(text)
) {
  category = "Pricing";

// Usability / onboarding / discoverability
} else if (
  /confus|difficult|can't find|cannot find|don't understand|do not understand|how to|find my way|not sure (where|which|how)|where (should|do) i|where .* (reports?|dashboard)|too many clicks?|many clicks?|hard to figure out|hard to use|figure out|trouble finding|discover|getting started|start with|setup|set up|onboarding|tutorial|step[- ]by[- ]step|guided setup|recommended dashboard|terminology|term .* (mean|means)|tooltip|tooltips|explanation|mobile|zoom in|buttons overlap|unusable|self[- ]sufficient/.test(text)
) {
  category = "Usability";

// Praise
} else if (
  /enjoy|love|great|thank|really like|awesome|helpful|useful|looks good|good product|promising|intuitive|powerful|valuable|nice/.test(text)
) {
  category = "Praise";
}


/*
 * URGENCY
 *
 * High:
 * - operationally blocking issues
 * - incorrect/missing business data
 * - security/access issues
 * - data loss
 * - compliance
 * - crashes/broken functionality
 * - explicit urgency
 *
 * Low:
 * - praise
 * - ordinary feature requests/customization
 *
 * Otherwise Medium.
 */

let urgency = "Medium";

const explicitHighUrgency =
  /asap|urgent|immediately|critical|blocking|block(ed|ing)|daily operations|our processes|cannot operate|can't operate/.test(text);

const highImpactData =
  /incorrect|wrong|inaccurate|doesn't match|does not match|mismatch|missing .* employees|employees .* missing|data completeness|data loss|lost changes|lost data/.test(text);

const highImpactSecurity =
  /sensitive employee information|sensitive data|unauthorized|access control|role[- ]based|permission|sso|single sign[- ]on|authentication|compliance deadline|audit log/.test(text);

const highImpactFailure =
  /crash|crashes|crashed|broken|failed|failure|unable to save|lost changes|not working|doesn't work|does not work/.test(text);

if (
  explicitHighUrgency ||
  highImpactData ||
  highImpactSecurity ||
  highImpactFailure
) {
  urgency = "High";
} else if (
  category === "Praise" ||
  category === "Feature Request" ||
  category === "Customization"
) {
  urgency = "Low";
}


/*
 * REVIEW
 *
 * Review very short/ambiguous feedback and feedback that
 * couldn't be confidently classified.
 */

const needs_review =
  category === "Other" ||
  text.length < 10 ||
  /^(not sure|unsure|idk|unknown|n\/a)$/.test(text);


/*
 * THEME
 *
 * More granular than the original theme rules.
 * The first matching theme wins.
 */

const feedback = text;

let theme = "Other";

if (
  /slow|too slow|lag|loading|performance|takes too long|take(s)? forever|time(s|d)? ?out|30[- ]?60 seconds|two minutes|peak hours?|reporting cycle/.test(feedback)
) {
  theme = "Dashboard Performance";

} else if (
  /export|download|csv|excel|pdf|report(s)?|scheduled report|custom report|historical reports?|email .* report/.test(feedback)
) {
  theme = "Reporting and Export";

} else if (
  /password|login|sign in|log in|authentication|sso|single sign[- ]on|identity provider|okta|role[- ]based|permissions?|access control/.test(feedback)
) {
  theme = "Login and Access";

} else if (
  /onboarding|getting started|guided setup|tutorial|step[- ]by[- ]step|confus|difficult|can't find|cannot find|don't understand|too many clicks?|discover|terminology|tooltip|mobile|unusable/.test(feedback)
) {
  theme = "Onboarding and Usability";

} else if (
  /incorrect|wrong|inaccurate|doesn't match|does not match|mismatch|discrepanc|headcount .* (wrong|incorrect)|figures .* (wrong|incorrect)/.test(feedback)
) {
  theme = "Data Accuracy";

} else if (
  /sync|synchroni[sz]|last synced|last sync|real[- ]?time|stale data|data freshness|timestamp/.test(feedback)
) {
  theme = "Data Synchronization";

} else if (
  /import|upload|spreadsheet|employee file|file format|rejected rows|failed import|import failed/.test(feedback)
) {
  theme = "Data Import";

} else if (
  /integrat(e|ion|ions|ing)|hris|payroll|api\b|internal dashboard/.test(feedback)
) {
  theme = "Integrations";

} else if (
  /benchmark|benchmarking|industry data|industry benchmark|similar size|same industry|anonymized industry/.test(feedback)
) {
  theme = "Benchmarking";

} else if (
  /attrition|turnover|engagement|predictive analytics|predictive|actionable insights?|recommendations?|suggested next steps?|workforce planning|headcount planning|hiring needs?/.test(feedback)
) {
  theme = "Analytics and Insights";

} else if (
  /audit logs?|audit trail|who viewed|who edited|who exported|who deleted|compliance deadline|compliance alert/.test(feedback)
) {
  theme = "Audit and Compliance";

} else if (
  /customiz(e|ation)|customise|custom field|bulk edit|bulk editing|dark mode|multi[- ]language|localized reports?/.test(feedback)
) {
  theme = "Customization";

} else if (
  /pricing|price|cost|expensive|justify .* cost|flexible plan|growing (business|team)/.test(feedback)
) {
  theme = "Pricing";
}


/*
 * Return original payload plus classification fields.
 */
return {
  ...$json,
  category,
  urgency,
  needs_review,
  theme
};
